    if (isMkt()) { $("#ra-new").onclick = () => accountForm(null); $("#ra-imp").onclick = importDialog; }
    let accs, tch, cfg; try { [accs, tch, cfg] = await Promise.all([M().accounts(), M().touches(), M().cfg()]); } catch (e) { $("#ra-body").innerHTML = errBox(e); return; }
    const rows = accs.map((a) => Object.assign({ sc: G().scoreAccount(a, { cfg, touches: tch.filter((t) => t.accountId === a.id) }) }, a))
