  const parseContacts = (t) => String(t || "").split(/\n+/).map((l) => l.trim()).filter(Boolean).map((l) => { const [name, role, phone, email, source, dm] = l.split("|").map((x) => (x || "").trim()); return { name, role, phone, email, source, decisionMaker: /decision|yes|dm/i.test(dm || "") }; });
