  /** Import researched accounts from CSV / Excel with fixed column names (company, project, segment, location, website, source, verified, stage, procurement, products, notes). */
  function importDialog() {
    U.pickFile(".csv,.xlsx,text/csv", async (file) => {
      try { let rows = /\.xlsx$/i.test(file.name) ? await DPLeadImport.parseXlsx(await file.arrayBuffer()) : DPLeadImport.parseCsv(await file.text());
        const head = rows.shift().map((h) => String(h).trim().toLowerCase()), ix = (...n) => head.findIndex((h) => n.some((x) => h === x || h.includes(x)));
        const c = { company: ix("company", "developer", "organisation"), project: ix("project"), segment: ix("segment", "type"), location: ix("location", "city"), website: ix("website"), source: ix("source"), verifiedAt: ix("verified"), stage: ix("stage"), procurementBy: ix("procurement", "handover"), products: ix("products"), notes: ix("notes", "summary") };
        if (c.company < 0) throw new Error("The file needs a 'company' column.");
        const segOf = (s) => Object.keys(G().SEGMENTS).find((k) => k === String(s || "").toLowerCase().trim() || G().SEGMENTS[k].toLowerCase() === String(s || "").toLowerCase().trim()) || "other";
        const stOf = (s) => Object.keys(G().STAGES).find((k) => k === String(s || "").toLowerCase().trim() || G().STAGES[k].toLowerCase().startsWith(String(s || "").toLowerCase().trim())) || "unknown";
        const data = rows.map((r) => ({ company: r[c.company], project: c.project >= 0 ? r[c.project] : "", segment: segOf(c.segment >= 0 ? r[c.segment] : ""), location: c.location >= 0 ? r[c.location] : "", website: c.website >= 0 ? r[c.website] : "", source: c.source >= 0 ? r[c.source] : "", verifiedAt: c.verifiedAt >= 0 && /^\d{4}-\d{2}-\d{2}$/.test(String(r[c.verifiedAt]).trim()) ? String(r[c.verifiedAt]).trim() : null, stage: stOf(c.stage >= 0 ? r[c.stage] : ""), procurementBy: c.procurementBy >= 0 && /^\d{4}-\d{2}-\d{2}$/.test(String(r[c.procurementBy]).trim()) ? String(r[c.procurementBy]).trim() : null, products: c.products >= 0 ? r[c.products] : "", notes: c.notes >= 0 ? r[c.notes] : "" }));
        if (!(await U.ask(`Import ${data.length} researched row(s)?`, "Rows without a source link are imported as PROVISIONAL. Duplicates of existing accounts are skipped. Contacts are not imported from files — add them with their source on each account.", [{ label: "Cancel", value: false, cls: "ghost" }, { label: "Import", value: true }]))) return;
        const r = await M().importAccounts(data, { origin: `Research import: ${file.name}` }); U.toast(`${r.added} added, ${r.skipped} already on the Radar${r.rejected.length ? `, ${r.rejected.length} rejected (no company)` : ""}.`, { ms: 8000 }); renderRadar();
      } catch (e) { U.toast(e.message, { err: true, ms: 8000 }); } });
  }

